// Cost per booked job, by source.
//
// The important rule here: a source that is genuinely free and a source whose
// cost nobody has told us yet must NEVER look the same. Both would otherwise
// show $0 spend, and the unpriced one would appear to be the best performer on
// the page. Every row states which it is.

const leads   = $('Get every lead').all().map(i => i.json);
const sources = $('Get the sources').all().map(i => i.json);
const period = 'Last 90 days';
const generated = new Date().toISOString();

const config = {};
for (const s of sources) if (s['Source']) config[s['Source']] = s;

const median = (nums) => {
  if (!nums.length) return null;
  const s = [...nums].sort((a, b) => a - b);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : Math.round((s[m - 1] + s[m]) / 2);
};

const bySource = {};
for (const l of leads) (bySource[l['Source'] || 'Unknown'] ??= []).push(l);

const rows = Object.entries(bySource).map(([source, rs]) => {
  const cfg     = config[source] || {};
  const basis   = cfg['Cost basis'] || 'Not yet priced';
  const won     = rs.filter(r => r['Stage'] === 'Won');
  const priced  = rs.filter(r => typeof r['Lead cost'] === 'number');
  const spend   = priced.reduce((t, r) => t + r['Lead cost'], 0);
  const revenue = won.reduce((t, r) => t + (r['Job value'] || 0), 0);
  const times   = rs.map(r => r['Response minutes']).filter(n => typeof n === 'number');

  // Decide, explicitly, whether the spend figure can be trusted.
  let quality, spendKnown, note;
  if (basis === 'Free by design') {
    quality = 'Free source';  spendKnown = true;
    note = `No per-lead cost by nature (${rs.length} leads)`;
  } else if (basis === 'Cost sits elsewhere') {
    quality = 'Cost counted elsewhere'; spendKnown = false;
    note = `Cost belongs to the originating source (${rs.length} leads)`;
  } else if (priced.length === 0) {
    quality = 'Spend unknown'; spendKnown = false;
    note = `NO COST ENTERED for ${rs.length} leads — spend is unknown, not zero`;
  } else if (priced.length < rs.length) {
    quality = 'Partly priced'; spendKnown = false;
    note = `Only ${priced.length} of ${rs.length} leads priced — spend is a floor, not a total`;
  } else {
    quality = 'Complete'; spendKnown = true;
    note = `${priced.length} of ${rs.length} leads priced`;
  }

  // Cost per booked job is only ever shown when the spend behind it is real.
  const canDivide = spendKnown && spend > 0 && won.length > 0;

  return {
    'Source': source,
    'Period': period,
    'Leads': rs.length,
    'Won': won.length,
    'Close rate %': rs.length ? Number((won.length / rs.length * 100).toFixed(1)) : 0,
    'Spend': spendKnown ? Number(spend.toFixed(2)) : null,
    'Revenue': Number(revenue.toFixed(2)),
    'Cost per booked job': canDivide ? Number((spend / won.length).toFixed(2)) : null,
    'Return per $1 spent': canDivide ? Number((revenue / spend).toFixed(2)) : null,
    'Median response mins': median(times),
    'Data quality': quality,
    'Priced leads': note,
    'Generated': generated,
  };
});

rows.sort((a, b) => (b.Revenue || 0) - (a.Revenue || 0));
return rows.map(json => ({ json }));

